program_source = '''def transform(grid):
    """Connect aligned same-color markers within the complete 8-separated cells."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_walls = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    col_walls = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def ranges(size, walls):
        result = []
        start = 0
        for wall in walls:
            if start < wall:
                result.append((start, wall))
            start = wall + 1
        if start < size:
            result.append((start, size))
        return result

    all_rows, all_cols = ranges(h, row_walls), ranges(w, col_walls)
    row_unit = all_rows[0][1] - all_rows[0][0]
    col_unit = all_cols[0][1] - all_cols[0][0]
    row_blocks = [(a, b) for a, b in all_rows if b - a == row_unit]
    col_blocks = [(a, b) for a, b in all_cols if b - a == col_unit]

    markers = {2: [], 3: []}
    for ri, (r0, r1) in enumerate(row_blocks):
        for ci, (c0, c1) in enumerate(col_blocks):
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if grid[r][c] in markers:
                        markers[grid[r][c]].append((ri, ci))

    painted = {}
    for color, points in markers.items():
        for i, (r1, c1) in enumerate(points):
            for r2, c2 in points[i + 1:]:
                if r1 == r2:
                    distance = abs(c2 - c1)
                    if distance < (3 if color == 2 else 1):
                        continue
                    for c in range(min(c1, c2), max(c1, c2) + 1):
                        painted.setdefault((r1, c), set()).add(color)
                elif c1 == c2:
                    distance = abs(r2 - r1)
                    if distance < (3 if color == 2 else 1):
                        continue
                    for r in range(min(r1, r2), max(r1, r2) + 1):
                        painted.setdefault((r, c1), set()).add(color)

    for (ri, ci), colors in painted.items():
        color = 6 if len(colors) > 1 else next(iter(colors))
        r0, r1 = row_blocks[ri]
        c0, c1 = col_blocks[ci]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
